fect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.VIT, 6)\n    effect:addMod(xi.mod.CHR, 4)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 150)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/teleport_ring_altep.lua"]={["Path"]="scripts/items/teleport_ring_altep.lua",["SHA256"]="a55e33b942a143bab015bf7d6d56644f3071b87d0d67670b41a0d55dffda347d",["Text"]="-----------------------------------\n-- ID: 14666\n-- Teleport ring: Altep\n-- Enchantment: \"Teleport-Altep\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasKeyItem(xi.keyItem.ALTEPA_GATE_CRYSTAL) then\n        result = 445\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.ALTEP, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/teleport_ring_dem.lua"]={["Path"]="scripts/items/teleport_ring_dem.lua",["SHA256"]="137508164955987d778f261e6e73989070ea5c3cd94e682449827c992a8c157b",["Text"]="-----------------------------------\n-- ID: 14662\n-- Teleport ring: Dem\n-- Enchantment: \"Teleport-Dem\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasKeyItem(xi.keyItem.DEM_GATE_CRYSTAL) then\n        result = 445\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.DEM, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/teleport_ring_holla.lua"]={["Path"]="scripts/items/teleport_ring_holla.lua",["SHA256"]="df8c910155a0e5bcf3baa