= function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.VAHZL, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/teleport_ring_yhoat.lua"]={["Path"]="scripts/items/teleport_ring_yhoat.lua",["SHA256"]="8742343d68ad673f49081b6333de5fa09a984e504b4699492b5d6aa22ea0d377",["Text"]="-----------------------------------\n-- ID: 14665\n-- Teleport ring: Yhoat\n-- Enchantment: \"Teleport-Yhoat\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasKeyItem(xi.keyItem.YHOATOR_GATE_CRYSTAL) then\n        result = 445\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.YHOAT, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/temple_knights_arrow.lua"]={["Path"]="scripts/items/temple_knights_arrow.lua",["SHA256"]="8ab0b1902356c8c5dc798edb5073b0c059cc0c7fa15a7d6c8d92d52cc292be12",["Text"]="-----------------------------------\n-- ID: 18738\n-- Item: Temple Knights Arrow\n-- Additional effect: Fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 10 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.FIRE,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/temple_knights_quiver.lua"]={["Path"]="scripts/items/temple_knights_quiver.lua",["SHA256"]="3d63d912236f08322778753e45d7aba6a956ebc6c19d8c3b972a05c00dda5cdc",["Text"]="-----------------------------------\n-- ID: 15956\n-- Temple Knight's Quiver\n-- When used, you will obtain one Temple Knight's Arrow\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.TEMPLE_KNIGHTS_ARROW, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/temple_truffle.lua"]={["Path"]="scripts/items/temple_truffle.lua",["SHA256"]="fb8ddc09a0a84be241fb727c7e70dccb71b2ec402896fa66020103542e3fae2c",["Text"]="-----------------------------------\n-- ID: 5916\n-- Item: Temple Truffle\n-- Food Effect: 3 Min, All Races\n-----------------------------------\n-- Strength 1\n-- Base speed 10% or +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 1)\n    effect:addMod(xi.mod.MOVE_SPEED_QUICKENING, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/thief_die.lua"]={["Path"]="scripts/items/thief_die.lua",["SHA256"]="5b4ad56cb56b880ade5ab6855b671fe113b353fcb24a3fe0b4feab70a80136f8",["Text"]="-----------------------------------\n-- ID: 5482\n-- Thief Die\n-- Teaches the job ability Rogue's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.ROGUES_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.ROGUES_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/throwing_weapon_enchiridion.lua"]={["Path"]="scripts/items/throwing_weapon_enchiridion.lua",["SHA256"]="2f5d60b9af19034fc3c7b31821920e65cd9879253897453ad725c50595a8fb5b",["Text"]="-----------------------------------\n-- ID: 6161\n-- Item: T.W. Enchiridion\n-- A guide to the finer points of hurling projectile objects at opponents,\n-- written by an anonymous individual.\n-- Adventurers note that reading it increases one's throwing skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.THROWING)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.THROWING)\nend\n\nreturn itemObject\n"},["scripts/items/thunder_card_case.lua"]={["Path"]="scripts/items/thunder_card_case.lua",["SHA256"]="0568c45e1f2cb44c464a2bd44dac75cc01b377848fa0cb60d04adfdebc66cff8",["Text"]="-----------------------------------\n-- ID: 5406\n-- Thunder Card Case\n-- When used, you will obtain one stack of Thunder Cards\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.THUNDER_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/thunder_mittens.lua"]={["Path"]="scripts/items/thunder_mittens.lua",["SHA256"]="fffff1d5ddf110a62c933f991a0ed8e6e490f9c0e0a5c7b675e0cafb3d37d1b5",["Text"]="-----------------------------------\n-- ID: 14987\n-- Thunder Mittens\n--  Enchantment: \"Enthunder\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local fakeSpell = GetSpell(xi.magic.spell.ENTHUNDER)\n    xi.spells.enhancing.useEnhancingSpell(target, target, fakeSpell)\nend\n\nreturn itemObject\n"},["scripts/items/thunder_spirit_pact.lua"]={["Path"]="scripts/items/thunder_spirit_pact.lua",["SHA256"]="34cac49a1146c64deda863a8de15d173ef9a51b46c964f322c9c597cec794a3f",["Text"]="-----------------------------------\n-- ID: 4900\n-- Thunder Spirit Pact\n-- Teaches the summoning magic Thunder Spirit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.THUNDER_SPIRIT)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.THUNDER_SPIRIT)\nend\n\nreturn itemObject\n"},["scripts/items/thunder_staff.lua"]={["Path"]="scripts/items/thunder_staff.lua",["SHA256"]="4d8ad5ad6ee33445088bf91b620a1c663e800bd0a56708fcf73f0b9a17f6feb9",["Text"]="-----------------------------------\n-- ID: 17553\n-- Item: Thunder Staff\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 15, -- guessed\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/thundercloud.lua"]={["Path"]="scripts/items/thundercloud.lua",["SHA256"]="bf52f8c740b5318f4ade666402c85fae3b2983f853c17e05f645bc45d37c4ed7",["Text"]="-----------------------------------\n-- ID: 16869\n-- Item: Thundercloud\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 6,\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/thundermelon.lua"]={["Path"]="scripts/items/thundermelon.lua",["SHA256"]="518425968ab432ba6a43a0b50d721433754490b6ee619d892fbaec1e4c19bdb2",["Text"]="-----------------------------------\n-- ID: 4412\n-- Item: thundermelon\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -6\n-- Intelligence 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -6)\n    effect:addMod(xi.mod.INT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/thunderstorm_schema.lua"]={["Path"]="scripts/items/thunderstorm_schema.lua",["SHA256"]="c9b3cfc663c67edeebeab36d3beb21ec9df69141da84c52ef1d32b19c208c27b",["Text"]="-----------------------------------\n-- ID: 6051\n-- Thunderstorm Schema\n-- Teaches the white magic Thunderstorm\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.THUNDERSTORM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.THUNDERSTORM)\nend\n\nreturn itemObject\n"},["scripts/items/tidal_talisman.lua"]={["Path"]="scripts/items/tidal_talisman.lua",["SHA256"]="583c994f8a63b729f0f4778846e9f26fc0e23a8bb38837212a0d4f02952d4f6d",["Text"]="-----------------------------------\n-- ID: 11290\n-- Item: tidal talisman\n-----------------------------------\nrequire('scripts/globals/teleports')\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local zoneId = target:getZoneID()\n    local destZoneData = xi.teleport.tidalDestinations[zoneId]\n\n    if\n        destZoneData and\n        target:hasVisitedZone(destZoneData[5])\n    then\n        return 0\n    end\n\n    return 56\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.TIDAL_TALISMAN, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/tiger_cod.lua"]={["Path"]="scripts/items/tiger_cod.lua",["SHA256"]="b4f2c72a1d8aabc49554f37272941ede8f193351eec15fb6596a0c32ce22dd94",["Text"]="-----------------------------------\n-- ID: 4483\n-- Item: tiger_cod\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/timbre_timbers_salad.lua"]={["Path"]="scripts/items/timbre_timbers_salad.lua",["SHA256"]="17d0f35c8149099856d0dc5a05e53f102a9c7e6f1238985fa60c2c7b9e668315",["Text"]="-----------------------------------\n-- ID: 4321\n-- Item: timbre_timbers_salad\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Magic 20\n-- Agility 5\n-- Vitality -1\n-- Ranged ACC % 8\n-- Ranged ACC Cap 15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.AGI, 5)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.FOOD_RACCP, 8)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/timbre_timbers_taco.lua"]={["Path"]="scripts/items/timbre_timbers_taco.lua",["SHA256"]="b1bcee367cd43e067d7a327d97c322e1babac2430619030234b5cd10eaba427f",["Text"]="-----------------------------------\n-- ID: 5173\n-- Item: timbre_timbers_taco\n-- Food Effect: 1hour, All Races\n-----------------------------------\n-- MP 20\n-- Vitality -1\n-- Agility 5\n-- MP Recovered While Healing 3\n-- Ranged Accuracy % 8 (cap 15)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.AGI, 5)\n    effect:addMod(xi.mod.MPHEAL, 3)\n    effect:addMod(xi.mod.FOOD_RACCP, 8)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tiny_goldfish.lua"]={["Path"]="scripts/items/tiny_goldfish.lua",["SHA256"]="2835123d1380fe73b1b3c4683c5818a82ab35a5cbc164eecf8c5817acb810066",["Text"]="-----------------------------------\n-- ID: 4310\n-- Item: tiny_goldfish\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/titanium_bolt_quiver.lua"]={["Path"]="scripts/items/titanium_bolt_quiver.lua",["SHA256"]="b47d870f2de27c0ed45abdf88ecdf9e2bec18fe458e79a756230eb6b492dcdd0",["Text"]="-----------------------------------\n-- ID: 6205\n-- Item: T. Bolt Quiver\n-- When used, you will obtain one stack of Titanium Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.TITANIUM_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/titanium_bullet_pouch.lua"]={["Path"]="scripts/items/titanium_bullet_pouch.lua",["SHA256"]="dfd496e50bf0add7871f4901a9eb771e6e419e1c2be03b22e6e6d61732bfb6b9",["Text"]="-----------------------------------\n-- ID: 6209\n-- Ti. Bull. Pouch\n-- When used, you will obtain one stack of Titanium Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.TITANIUM_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/titans_cudgel.lua"]={["Path"]="scripts/items/titans_cudgel.lua",["SHA256"]="62d646f957479484d0b4326cba937a1ddad6b7748e879432bdf7051bafad6879",["Text"]="-----------------------------------\n-- ID: 17438\n-- Item: Titan's Cudgel\n-- Additional effect: earth damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local chance = 3 -- TODO: check scaling on non-earthsday\n\n    if VanadielDayOfTheWeek() == xi.day.EARTHSDAY then\n        chance = xi.additionalEffect.linearProcRate(dStat, 140, 15, 50) -- Numbers are smoothed out a bit. Scale from 15% at dINT 0 to 50% at +140 DINT\n    end\n\n    local pTable =\n    {\n        chance         = chance,\n        basePower      = math.randomInt(18, 25),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.EARTH,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/togakushi_shuriken_pouch.lua"]={["Path"]="scripts/items/togakushi_shuriken_pouch.lua",["SHA256"]="1a8fc3c894ec67054ca576e49ac0b36093ce8aa30e03644a07979e99814401b5",["Text"]="-----------------------------------\n-- ID: 6301\n-- Item: Toga. Sh. Pouch\n-- When used, you will obtain one stack of Togakushi Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.TOGAKUSHI_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/tonosama_rice_ball.lua"]={["Path"]="scripts/items/tonosama_rice_ball.lua",["SHA256"]="65698316bbb1dd87db5b1d7a836ab16fb440232478aa3748e0f7d2e817cbda41",["Text"]="-----------------------------------\n-- ID: 4277\n-- Item: Tonosama Rice Ball\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +15\n-- Dex +3\n-- Vit +3\n-- Chr +3\n-- Effect with enhancing equipment (Note: these are latents on gear with the effect)\n-- Atk +50\n-- Def +30\n-- Double Attack +1%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 15)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.CHR, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/toolbag_chonofuda.lua"]={["Path"]="scripts/items/toolbag_chonofuda.lua",["SHA256"]="84c2d8b00432ad31ab945931b6116e136964ab83f9162b787