---\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SHINOBI_TABI, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/toolbag_soshi.lua"]={["Path"]="scripts/items/toolbag_soshi.lua",["SHA256"]="1d76f5c3585a230296c8ee89fe6a43225f84bbdedb023c77ffa3b16768096a38",["Text"]="-----------------------------------\n-- ID: 5734\n-- Toolbag Soshi\n-- When used, you will obtain one stack of soshi\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SOSHI, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/toolbag_tsurara.lua"]={["Path"]="scripts/items/toolbag_tsurara.lua",["SHA256"]="390deb449738e71b1cb2370624b40298c291d7e3aafc8f08996318bb99556dc0",["Text"]="-----------------------------------\n-- ID: 5309\n-- Toolbag Tsura\n-- When used, you will obtain one stack of tsurara\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.TSURARA, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/toolbag_uchitake.lua"]={["Path"]="scripts/items/toolbag_uchitake.lua",["SHA256"]="615586cfb6daa191f56371c0b76c6177462620941360cfdd1a216e2aac212d48",["Text"]="-----------------------------------\n-- ID: 5308\n-- Toolbag Uchi\n-- When used, you will obtain one stack of uchitake\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.UCHITAKE, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/tortilla.lua"]={["Path"]="scripts/items/tortilla.lua",["SHA256"]="9533754859f00a1df0c09d7eba6e5de0d8bb553ebdbe1383a4391246e57737b6",["Text"]="-----------------------------------\n-- ID: 4408\n-- Item: tortilla\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 6\n-- Dexterity -1\n-- Vitality 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 6)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.VIT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tortilla_buena.lua"]={["Path"]="scripts/items/tortilla_buena.lua",["SHA256"]="b85b6cf7b5a772099c27f626c920e92114ee104f2d9d887c5962f1cdb79b8155",["Text"]="-----------------------------------\n-- ID: 5181\n-- Item: tortilla_buena\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 8\n-- Vitality 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 8)\n    effect:addMod(xi.mod.VIT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tough_belt.lua"]={["Path"]="scripts/items/tough_belt.lua",["SHA256"]="686644a33c167f604b51079e01426244b7805436fd53ce163651f628e31d9560",["Text"]="-----------------------------------\n-- ID: 15864\n-- Item: tough_belt\n-- Item Effect: VIT +3\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.VIT_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TOUGH_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.VIT_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TOUGH_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.TOUGH_BELT) then\n        target:addStatusEffect(xi.effect.VIT_BOOST, { power = 3, duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.TOUGH_BELT })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/town_moogle_shield.lua"]={["Path"]="scripts/items/town_moogle_shield.lua",["SHA256"]="10bb1b5aec7a8b3aa019cf9b21256dd62781a0c00491cb8894d1411ae76fedbe",["Text"]="-----------------------------------\n-- ID: 16182\n-- Town Moogle Shield\n-- Enchantment: 60Min, Costume - Moogle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 2308, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/trail_cookie.lua"]={["Path"]="scripts/items/trail_cookie.lua",["SHA256"]="dfdbcc219334426feee690104b6ca95e342bd29af0785a6228688e1c99931979",["Text"]="-----------------------------------\n-- ID: 5940\n-- Item: Trail Cookie\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- MP Healing 5\n-- Aquan Killer 12\n-- Sleep Resist 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 5)\n    effect:addMod(xi.mod.AQUAN_KILLER, 12)\n    effect:addMod(xi.mod.SLEEPRES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/treat_staff.lua"]={["Path"]="scripts/items/treat_staff.lua",["SHA256"]="8664ac04d419036a5539d9efe1119f5467e8db07e6d01a1e16626a7672ff8aba",["Text"]="-----------------------------------\n-- ID: 17566\n-- Treat Staff\n-- Latent effect during Harvest Festival events\n--\n-- This effect is triggered similar to an Additional Effect when attacking monsters.\n-- when the effect activates, you will be Warped to your Home Point.\n-- This allegedly can trigger on missed attacks and Weapon Skills. TODO: confirm\n-- There is no animation present when this effect activates, you will simply disappear and reappear at your Home Point.\n-- According to https://wiki.ffo.jp/html/3736.html the effect is\n-- only moon phase based when the Harvest Festival event is NOT active but ...\n-- Hours were spent attempting to trigger a proc during the moon conditions describe to no avail.\n-- (it wasn't changed, seems that information was simply incorrect)\n--\n-- Calling it 10% proc rate, this is tough to get a decent sample for even during harvest fest event.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemEquip  = function(user, item)\n    user:addListener('ATTACK', 'TREAT_STAFF_MELEE', function(player, target, action)\n        if\n            math.randomInt(1, 100) <= 10 and\n            xi.events.harvestFestival.isHalloweenEnabled()\n        then\n            -- Need a small delay for the swing animation.\n            player:timer(100, function(playerArg)\n                -- We normally NEVER do this, but we want to skip animating the warp itself.\n                playerArg:warp()\n            end)\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(user, item)\n    user:removeListener('TREAT_STAFF_MELEE')\n    -- user:removeListener('TREAT_STAFF_WS')\n    -- user:removeListener('TREAT_STAFF_MISSED')\nend\n\nreturn itemObject\n"},["scripts/items/treat_staff_ii.lua"]={["Path"]="scripts/items/treat_staff_ii.lua",["SHA256"]="fe8c9fb0c4d2bb8ba6e768cde966463130b74c58ef940dbab06427bafea1661b",["Text"]="-----------------------------------\n--  ID: 17588\n--  Treat staff II\n--  Transports the user to their Home Point\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:warp()\nend\n\nreturn itemObject\n"},["scripts/items/tredecim_scythe.lua"]={["Path"]="scripts/items/tredecim_scythe.lua",["SHA256"]="8199aac9ceaaf14950b5b77e191be889bbf13ddaaa171819c3ea6ca0d7937da8",["Text"]="-----------------------------------\n-- ID: 18052\n-- Tredecim Scythe\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemEquip = function(target, item)\n    target:addListener('MELEE_SWING_HIT', 'TREDECIM_MELEE_SWING_HIT', function(playerArg, targetArg, attackArg)\n        local mainWeapon = playerArg:getEquippedItem(xi.slot.MAIN)\n        if mainWeapon and mainWeapon:getID() == xi.item.TREDECIM_SCYTHE then\n            local exData = mainWeapon:getExDataRaw()\n            local count  = exData[0]\n\n            if count % 13 == 12 then\n                attackArg:setCritical(true)\n            end\n\n            mainWeapon:setExDataRaw({ [0] = (count + 1) % 13 })\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:removeListener('TREDECIM_MELEE_SWING_HIT')\nend\n\nreturn itemObject\n"},["scripts/items/trick_staff_ii.lua"]={["Path"]="scripts/items/trick_staff_ii.lua",["SHA256"]="6c9e32b388c21b6e5167f4cd6f05fd9bd076a3a1fc62f4cb05dd71784f199a8a",["Text"]="-----------------------------------\n--  ID: 17587\n--  Trick Staff II\n--  Transports the user to their Home Point\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:warp()\nend\n\nreturn itemObject\n"}};
